function localToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
async function seed(){const parameters=(await loadParameters()).default,d=createDataset();for(const table of parameters.tables)addReferenceRows(d,table.type,table.headers,table.rows,table);return d;}
function persist(){try{localStorage.setItem('controlops-v5-settings',JSON.stringify(state.settings));}catch{toast('No se pudieron guardar los ajustes en este equipo.');}}
function openWorkspaceDb(){
 if(!globalThis.indexedDB)return Promise.reject(new Error('El navegador no ofrece almacenamiento local recuperable.'));
 if(workspaceDbPromise)return workspaceDbPromise;
 workspaceDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(WORKSPACE_DB,WORKSPACE_SCHEMA);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(WORKSPACE_STORE))db.createObjectStore(WORKSPACE_STORE);};request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>{db.close();workspaceDbPromise=null;};resolve(db);};request.onerror=()=>{workspaceDbPromise=null;reject(request.error||new Error('No se pudo abrir el almacenamiento local.'));};request.onblocked=()=>{workspaceDbPromise=null;reject(new Error('Otra pestaña está usando la sesión local.'));};});
 return workspaceDbPromise;
}
async function readWorkspaceSnapshot(){
 if(!globalThis.indexedDB)return null;const db=await openWorkspaceDb();
 return new Promise((resolve,reject)=>{const transaction=db.transaction(WORKSPACE_STORE,'readonly'),request=transaction.objectStore(WORKSPACE_STORE).get(WORKSPACE_KEY);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error||new Error('No se pudo leer la sesión local.'));transaction.onabort=()=>reject(transaction.error||new Error('La lectura local fue cancelada.'));});
}
async function writeWorkspaceSnapshot(snapshot){
 const db=await openWorkspaceDb();
 return new Promise((resolve,reject)=>{const transaction=db.transaction(WORKSPACE_STORE,'readwrite');transaction.objectStore(WORKSPACE_STORE).put(snapshot,WORKSPACE_KEY);transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error||new Error('No se pudo guardar la sesión local.'));transaction.onabort=()=>reject(transaction.error||new Error('El guardado local fue cancelado.'));});
}
async function clearWorkspaceSnapshot(){
 if(!globalThis.indexedDB)return;const db=await openWorkspaceDb();
 return new Promise((resolve,reject)=>{const transaction=db.transaction(WORKSPACE_STORE,'readwrite');transaction.objectStore(WORKSPACE_STORE).delete(WORKSPACE_KEY);transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error||new Error('No se pudo borrar la sesión local.'));transaction.onabort=()=>reject(transaction.error||new Error('El borrado local fue cancelado.'));});
}
function savedTime(value){if(!value)return'';try{return new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value));}catch{return'';}}
function renderSaveStatus(){
 const element=$('saveStatus');if(!element)return;const visible=state.workbooks.length>0;element.hidden=!visible;if(!visible)return;
 const label=state.saveState==='saving'?'Cargando…':state.saveState==='error'?'Sesión activa':state.restored?'✓ Carga verde · recuperada':'✓ Carga verde';
 element.className=`save-status ${state.saveState}`;element.textContent=label;element.title=state.savedAt?`Respaldo local · ${savedTime(state.savedAt)}`:'Respaldo local activo.';
}
async function saveWorkspaceSnapshot(){
 if(!state.workbooks.length){await clearWorkspaceSnapshot();state.savedAt=0;state.saveState='idle';state.restored=false;renderSaveStatus();return true;}
 state.saveState='saving';renderSaveStatus();const savedAt=Date.now(),snapshot={schema:WORKSPACE_SCHEMA,savedAt,sequence:state.sequence,sourceSequence:state.sourceSequence,lastLoad:state.lastLoad,files:state.files.slice(-48),workbooks:state.workbooks};
 try{await writeWorkspaceSnapshot(snapshot);state.savedAt=savedAt;state.saveState='saved';state.restored=false;renderSaveStatus();if(!storagePersistenceRequested&&navigator.storage?.persist){storagePersistenceRequested=true;navigator.storage.persist().catch(()=>false);}return true;}catch(error){console.error(error);state.saveState='error';renderSaveStatus();return false;}
}
async function restoreWorkspaceSnapshot(){
 const snapshot=await readWorkspaceSnapshot();if(!snapshot)return false;
 if(snapshot.schema!==WORKSPACE_SCHEMA||!Array.isArray(snapshot.workbooks)||!snapshot.workbooks.length||snapshot.workbooks.length>12)throw new Error('La sesión local no tiene un formato válido.');
 for(const record of snapshot.workbooks)if(!record||typeof record.name!=='string'||!record.dataset||!Array.isArray(record.dataset.salesFacts)||!Array.isArray(record.dataset.usageFacts))throw new Error('La sesión local está incompleta.');
 const selection=selectRecentWorkbooks(snapshot.workbooks),rebuilt=await seed();for(const record of selection.selected){validateCeCo(rebuilt,record.dataset);mergeDataset(rebuilt,record.dataset);}
 state.dataset=rebuilt;state.workbooks=selection.selected;state.files=Array.isArray(snapshot.files)?snapshot.files:selection.selected.map(record=>({id:record.sourceId,name:record.name,statusCode:'selected',status:'Recuperado',reason:freshnessStatus(record)}));state.sequence=Math.max(Number(snapshot.sequence)||0,...selection.selected.map(record=>Number(record.sequence)||0));state.sourceSequence=Math.max(Number(snapshot.sourceSequence)||0,selection.selected.length);state.lastLoad=snapshot.lastLoad||null;state.savedAt=Number(snapshot.savedAt)||Date.now();state.saveState='restored';state.restored=true;return true;
}
