 const key=store(),currentToday=localToday(),settings=state.settings.orderSettings[key]&&typeof state.settings.orderSettings[key]==='object'?state.settings.orderSettings[key]:{today:currentToday,delivery:'',receptions:[],provider:'DIA'};
 state.settings.orderSettings[key]=settings;const savedProvider=providerAlias(settings.provider||'DIA');
 settings.receptions=[...new Set((Array.isArray(settings.receptions)?settings.receptions:[]).map(Number).filter(day=>Number.isInteger(day)&&day>=0&&day<7))].sort((a,b)=>a-b);
