 state.loadingTransit=true;draw();
 const current=state.settings.transitOrders[store()]||[],usedOrders=new Set(current.map(order=>order.purchaseOrder)),usedFingerprints=new Set(current.map(order=>order.fileFingerprint).filter(Boolean)),accepted=[],errors=[],motorIdentity={ceco:store(),name:state.dataset.storeCatalog.get(store())||''};let movedTo='';
