async function resetWorkspace(){
 $('confirmResetButton').disabled=true;$('cancelResetButton').disabled=true;
 try{await clearWorkspaceSnapshot();localStorage.removeItem('controlops-v5-settings');state.settings={};ensureSettingsBuckets();state.dataset=createDataset();state.files=[];state.workbooks=[];state.sequence=0;state.sourceSequence=0;state.lastLoad=null;state.filters={};state.maxminSelected.clear();state.orderResults=[];state.transitAudit=null;state.activeTransitOrders=[];state.result=null;state.report=null;state.reportModule=null;state.openMultiFilter='';state.savedAt=0;state.saveState='idle';state.restored=false;state.module='menu';$('resetConfirmation').close();draw();location.reload();}catch(error){console.error(error);toast('No se pudieron borrar todos los datos locales. Cierra otras pestañas e inténtalo de nuevo.');}
 finally{$('confirmResetButton').disabled=false;$('cancelResetButton').disabled=false;}
}
async function initialize(){
 const removedTransit=pruneUnverifiedTransitOrders();let message='';state.loading=true;$('loading').hidden=false;$('progressText').textContent='Recuperando sesión local…';$('uploadButton').disabled=true;$('fileInput').disabled=true;
 try{if(await restoreWorkspaceSnapshot())message='Sesión recuperada: tus Motores siguen listos en este dispositivo.';}
 catch(error){console.error(error);try{await clearWorkspaceSnapshot();}catch(clearError){console.error(clearError);}state.dataset=createDataset();state.files=[];state.workbooks=[];state.savedAt=0;state.saveState='error';state.restored=false;message='La sesión guardada estaba incompleta. Carga nuevamente los Motores.';}
 finally{state.loading=false;$('loading').hidden=true;$('uploadButton').disabled=false;$('fileInput').disabled=false;draw();}
 if(removedTransit)message=[message,`${removedTransit} PDF anterior necesita validarse de nuevo por seguridad.`].filter(Boolean).join(' ');if(message)toast(message);
}

$('uploadButton').addEventListener('click',()=>$('fileInput').click());$('dropZone').addEventListener('click',()=>$('fileInput').click());$('fileInput').addEventListener('change',e=>loadFiles([...e.target.files]));
$('homeButton').addEventListener('click',()=>navigate('menu'));$('backButton').addEventListener('click',()=>navigate('menu'));$('excelButton').addEventListener('click',()=>exportFile('xlsx'));$('pdfButton').addEventListener('click',()=>exportFile('pdf'));
$('aboutButton').addEventListener('click',openAbout);$('closeAboutButton').addEventListener('click',()=>$('aboutDialog').close());
$('confirmButton').addEventListener('click',()=>$('confirmation').close());
$('resetButton').addEventListener('click',()=>$('resetConfirmation').showModal());$('cancelResetButton').addEventListener('click',()=>$('resetConfirmation').close());$('confirmResetButton').addEventListener('click',resetWorkspace);
document.addEventListener('dragover',e=>{e.preventDefault();});document.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length)loadFiles([...e.dataTransfer.files]);});
function closeMultiFilters(except=null){for(const details of document.querySelectorAll('details.multi-select[open]'))if(details!==except)details.open=false;if(!except)state.openMultiFilter='';}
document.addEventListener('toggle',e=>{const details=e.target;if(!details.matches?.('details.multi-select'))return;if(!details.open){if(state.openMultiFilter===details.dataset.multiName)state.openMultiFilter='';return;}state.openMultiFilter=details.dataset.multiName||'';closeMultiFilters(details);const search=details.querySelector('[data-multi-search]');if(search&&document.activeElement===details.querySelector('summary'))requestAnimationFrame(()=>search.focus());},true);
document.addEventListener('keydown',e=>{const daily=e.target.closest?.('[data-order-field="dailyUse"]');if(e.key==='Enter'&&daily){e.preventDefault();const inputs=[...document.querySelectorAll('[data-order-field="dailyUse"]')],next=inputs[inputs.indexOf(daily)+1];state.orderEditFocus=next?.dataset.key||'';daily.blur();restoreOrderEditFocus();return;}if(e.key!=='Escape')return;const details=e.target.closest?.('details.multi-select')||document.querySelector('details.multi-select[open]');if(details){state.openMultiFilter='';details.open=false;details.querySelector('summary')?.focus();}});
document.addEventListener('focusin',e=>{if(e.target.matches?.('[data-order-field="dailyUse"]'))e.target.select();});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.multiSearch===undefined)return;const menu=el.closest('.multi-menu'),query=normalize(el.value);let visible=0;for(const option of menu.querySelectorAll('[data-multi-option]')){const show=!query||normalize(option.textContent).includes(query);option.hidden=!show;if(show)visible++;}menu.dataset.empty=String(!visible);});
document.addEventListener('click',e=>{
 if(!e.target.closest('.multi-select'))closeMultiFilters();
 const direct=e.target.closest('[data-direct-app]');if(direct)publishDirectContext(direct.dataset.directApp);
 const target=e.target.closest('button');if(!target||state.loading)return;
 if(target.dataset.module)navigate(target.dataset.module);
 if(target.dataset.subtab){state.subtabs[state.module]=target.dataset.subtab;state.openMultiFilter='';draw();}
 if(target.dataset.peakBasis){filterState().peakBasis=target.dataset.peakBasis;draw();toast(target.dataset.peakBasis==='average'?'Objetivos calculados con promedio.':'Objetivos calculados con el comparable más reciente.');}
 if(target.dataset.cycleDay!==undefined){filterState().cycleDay=target.dataset.cycleDay;draw();}
 if(target.dataset.phTrendDay!==undefined){filterState().phTrendDay=target.dataset.phTrendDay;draw();}
 if(target.dataset.auditTicket){state.auditTicket=target.dataset.auditTicket;draw();}
 if(target.dataset.orderJump){target.dataset.orderJump==='top'?window.scrollTo({top:0,behavior:'smooth'}):document.getElementById(target.dataset.orderJump)?.scrollIntoView({behavior:'smooth',block:'start'});}
 if(target.dataset.clearMulti){state.openMultiFilter=target.dataset.clearMulti;filterState()[target.dataset.clearMulti]=[];state.page=0;draw();}
 if(target.dataset.closeMulti){state.openMultiFilter='';document.querySelector(`details[data-multi-name="${target.dataset.closeMulti}"]`)?.removeAttribute('open');}
 if(target.dataset.restore){delete state.settings.minimum[target.dataset.restore];persist();draw();}
 if(target.dataset.action==='clear-filters'){state.openMultiFilter='';state.filters[state.module]=state.module==='order'?{window:'21',provider:'DIA'}:{};if(state.module==='order'){orderSettingsForStore();persist();}state.page=0;draw();}
 if(target.dataset.action==='select-visible'){state.result.items.forEach(i=>state.maxminSelected.add(i.key));draw();toast(`${state.result.items.length} productos visibles seleccionados.`);}
 if(target.dataset.action==='clear-selection'){state.maxminSelected.clear();draw();toast('Selección de Max & Min vaciada.');}
 if(target.dataset.action==='clear-receptions'){const settings=orderSettingsForStore();settings.receptions=[];setOrderDelivery(settings,'');persist();draw();}
 if(target.dataset.action==='select-next-order'){const settings=orderSettingsForStore(),next=orderDateChoices(settings)[0];if(next){setOrderDelivery(settings,next);persist();draw();toast(`Pedido seleccionado: ${orderDateLabel(next)}.`);}}
 if(target.dataset.action==='continue-order-cycle'){const panel=document.getElementById('order-transit');if(panel){panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});}}
 if(target.dataset.action==='load-transit')document.getElementById('transitPdfInput')?.click();
 if(target.dataset.resetOrderUse){const input=state.settings.orders[target.dataset.resetOrderUse];if(input){delete input.dailyUse;persist();draw();toast('Uso diario restaurado al promedio histórico.');}}
 if(target.dataset.removeTransit){state.settings.transitOrders[store()]=(state.settings.transitOrders[store()]||[]).filter(order=>String(order.purchaseOrder)!==String(target.dataset.removeTransit));persist();draw();toast('Pedido en tránsito retirado.');}
 if(target.dataset.action==='prev'){state.page=Math.max(0,state.page-1);draw();}
 if(target.dataset.action==='next'){state.page++;draw();}
});
document.addEventListener('change',e=>{
 const el=e.target;if(state.loading)return;
 if(el.dataset.multiFilter){const name=el.dataset.multiFilter,current=new Set(filterState()[name]||[]);el.checked?current.add(el.value):current.delete(el.value);filterState()[name]=[...current];state.openMultiFilter=name;state.page=0;draw();}
 if(el.dataset.maxminSelect){el.checked?state.maxminSelected.add(el.dataset.maxminSelect):state.maxminSelected.delete(el.dataset.maxminSelect);draw();}
 if(el.dataset.filter){filterState()[el.dataset.filter]=el.value;if(state.module==='order'&&el.dataset.filter==='provider'){orderSettingsForStore();persist();}state.page=0;draw();}
 if(el.dataset.minimum){const v=Number(el.value);if(el.value===''||!Number.isFinite(v)||v<0){toast('Ingresa un mínimo de cero o mayor.');draw();return;}state.settings.minimum[el.dataset.minimum]=v;persist();draw();}
 if(el.dataset.presentation){state.settings.modes[el.dataset.presentation]=el.value;persist();draw();}
 if(el.dataset.orderField){let value=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(el.dataset.orderField==='dailyUse'&&value!==null&&(!Number.isFinite(value)||value<0)){toast('El uso diario debe ser cero o mayor.');draw();return;}if(el.dataset.orderField==='dailyUse'&&value!==null)value=oneDecimal(value);(state.settings.orders[el.dataset.key]||={})[el.dataset.orderField]=value;persist();draw();}
 if(el.dataset.orderSetting){const settings=orderSettingsForStore();if(el.dataset.orderSetting==='delivery')setOrderDelivery(settings,el.value);else settings[el.dataset.orderSetting]=el.value;persist();draw();}
 if(el.dataset.peakReal){const value=el.value===''?null:Number(el.value);if(value!==null&&(!Number.isFinite(value)||value<0)){toast('El resultado real debe ser cero o mayor.');draw();return;}if(value===null)delete state.settings.peakActuals[el.dataset.peakReal];else state.settings.peakActuals[el.dataset.peakReal]=Math.round(value);persist();draw();}
 if(el.dataset.cycleActivity){const value=el.value.trim();if(value)state.settings.cycleActivities[el.dataset.cycleActivity]=value;else delete state.settings.cycleActivities[el.dataset.cycleActivity];persist();draw();}
 if(el.id==='transitPdfInput')loadTransitPdfs(el.files);
 if(el.dataset.reception!==undefined){const settings=orderSettingsForStore(),days=settings.receptions||[],day=Number(el.dataset.reception);settings.receptions=(el.checked?[...new Set([...days,day])]:days.filter(x=>x!==day)).sort((a,b)=>a-b);if(settings.delivery&&!orderDateChoices(settings).includes(settings.delivery))setOrderDelivery(settings,'');persist();draw();}
 if(el.dataset.baked){const value=el.value===''?null:Number(el.value);(state.settings.baked[el.dataset.scope]||={})[el.dataset.baked]={stock:value};persist();draw();}
});
window.addEventListener('beforeunload',event=>{if(!state.loading&&state.saveState!=='saving')return;event.preventDefault();event.returnValue='';});
window.addEventListener('unhandledrejection',event=>{console.error(event.reason);toast('La operación no terminó. Revisa el archivo e inténtalo de nuevo.');});
try{draw();initialize();}catch(e){$('emptyState').innerHTML=`<h1>No se pudo iniciar Control Ops</h1><p>${esc(e.message)}</p>`;$('uploadButton').disabled=true;}
